package com.tamerslab.hardware.vpet

import java.nio.charset.StandardCharsets

/**
 * One entry of a recovered `LISTAS` table: `name~stage~attribute` (lector.js `fila`).
 * [stage] and [attribute] are null when the table entry leaves them empty.
 */
data class VpetListEntry(
    val name: String,
    val stage: Int?,
    val attribute: Int?,
)

/**
 * Loads the tables recovered from `lector.js` (`/vpet-lists.txt`, generated by
 * `tools/vpet/extract-lists.mjs`).
 *
 * The file lives in `src/main/resources` so it is available both on the JVM unit-test
 * classpath and inside the AAR. Lookups mirror lector.js `lista(k, i)` and `porClave(k, c)`:
 * flat lists (dm20, pen20, z1, z2, x0, x1, x2) are indexed by position, keyed lists
 * (dmc, penc) by their `VV-NN`/`V-NN` key.
 */
object VpetTables {

    private const val RESOURCE_PATH = "/vpet-lists.txt"
    private const val HEADER = "#vpet-lists-v1"

    private val values: Map<String, String> by lazy(VpetTables::load)
    private val flatSlots = HashMap<String, List<String>>()
    private val keyedSlots = HashMap<String, Map<String, String>>()

    /** All list names present in the generated file, in file order. */
    fun listNames(): Set<String> = values.keys

    /** Verbatim value of one generated list (null when the name is unknown). */
    fun rawValue(name: String): String? = values[name]

    /** Number of `|`-separated slots (index space) of one list. */
    fun slotCount(name: String): Int = slotsOf(name).size

    /** lector.js `lista(name, index)`: null for index 0, out-of-range or empty entries. */
    fun entry(listName: String, index: Int): VpetListEntry? {
        if (index <= 0) return null
        val slots = slotsOf(listName)
        if (index >= slots.size) return null
        return parseFlatRow(slots[index])
    }

    /** lector.js `porClave(name, key)`: null when the key is absent or the entry is empty. */
    fun keyedEntry(listName: String, key: String): VpetListEntry? = parseFlatRow(keyedOf(listName)[key])

    private fun slotsOf(listName: String): List<String> = synchronized(flatSlots) {
        flatSlots.getOrPut(listName) { (values[listName] ?: "").split(SPLIT_CHAR) }
    }

    private fun keyedOf(listName: String): Map<String, String> = synchronized(keyedSlots) {
        keyedSlots.getOrPut(listName) {
            val result = LinkedHashMap<String, String>()
            for (part in (values[listName] ?: "").split(SPLIT_CHAR)) {
                val separator = part.indexOf('=')
                if (separator > 0) result[part.substring(0, separator)] = part.substring(separator + 1)
            }
            result
        }
    }

    /** lector.js `fila(e)`: `name~stage~attribute`, empty fields become null. */
    private fun parseFlatRow(entry: String?): VpetListEntry? {
        if (entry.isNullOrEmpty()) return null
        val parts = entry.split('~')
        val name = parts[0]
        if (name.isEmpty()) return null
        val stage = parts.getOrNull(1)?.takeIf { it.isNotEmpty() }?.toIntOrNull()
        val attribute = parts.getOrNull(2)?.takeIf { it.isNotEmpty() }?.toIntOrNull()
        return VpetListEntry(name, stage, attribute)
    }

    private fun load(): Map<String, String> {
        val stream = VpetTables::class.java.getResourceAsStream(RESOURCE_PATH)
            ?: error("Missing classpath resource $RESOURCE_PATH; run `node tools/vpet/extract-lists.mjs`")
        val lines = stream.bufferedReader(StandardCharsets.UTF_8).use { it.readLines() }
        check(lines.isNotEmpty() && lines.first() == HEADER) {
            "Unexpected $RESOURCE_PATH header: ${lines.firstOrNull()}"
        }
        val result = LinkedHashMap<String, String>()
        for (line in lines.drop(1)) {
            if (line.isEmpty()) continue
            val separator = line.indexOf('\t')
            check(separator > 0) { "Malformed $RESOURCE_PATH line: $line" }
            result[line.substring(0, separator)] = line.substring(separator + 1)
        }
        check(result.isNotEmpty()) { "$RESOURCE_PATH contains no lists" }
        return result
    }

    private const val SPLIT_CHAR = '|'
}
